import itertools
H=W=7
def at(g,r,c): return g[r][c] if 0<=r<H and 0<=c<W else -1  # -1 = outside
targets = {(r,c):col for r,c,col in cells}

def neigh(r,c):
    return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)]

feats = {}
def F(name, fn):
    for (r,c),t in targets.items():
        feats.setdefault(name,[]).append((t, fn(r,c)))

# feature: count of same-color (8) neighbors in 8-neigh, with outside counted as 8 or as 0
F('same8', lambda r,c: sum(1 for p in neigh(r,c) if at(demo_in,*p)==8))
F('same8_out_as8', lambda r,c: sum(1 for p in neigh(r,c) if at(demo_in,*p)!=0))
F('diff8', lambda r,c: sum(1 for p in neigh(r,c) if at(demo_in,*p)==0))
F('diff8_out0', lambda r,c: sum(1 for p in neigh(r,c) if at(demo_in,*p)!=8))
F('orth', lambda r,c: sum(1 for dr,dc in((1,0),(-1,0),(0,1),(0,-1)) if at(demo_in,r+dr,c+dc)==8))
F('diag', lambda r,c: sum(1 for dr,dc in((1,1),(1,-1),(-1,1),(-1,-1)) if at(demo_in,r+dr,c+dc)==8))

