def runs(g,r,c):
    res={}
    for name,(dr,dc) in {'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}.items():
        n=0; rr,cc=r+dr,c+dc
        while 0<=rr<7 and 0<=cc<7 and g[rr][cc]==8: n+=1; rr+=dr; cc+=dc
        res[name]=n
    for name,(dr,dc) in {'UL':(-1,-1),'UR':(-1,1),'DL':(1,-1),'DR':(1,1)}.items():
        n=0; rr,cc=r+dr,c+dc
        while 0<=rr<7 and 0<=cc<7 and g[rr][cc]==8: n+=1; rr+=dr; cc+=dc
        res[name]=n
    return res

def blocks(r,c):
    out=[]
    for dr in(-1,0):
        for dc in(-1,0):
            blk=[(r+dr+i,c+dc+j) for i in range(2) for j in range(2)]
            if all(0<=rr<7 and 0<=cc<7 for rr,cc in blk):
                out.append(sum(1 for rr,cc in blk if demo_in[rr][cc]==8))
    return out

feat={}
for (r,c),t in targets.items():
