    f.update(runs(demo_in,r,c))
    b=blocks(r,c)
    for k in range(6): f[f'blk{k}']=sum(1 for x in b if x==k)
    f['maxblk']=max(b) if b else -1
    f['minblk']=min(b) if b else -1
    f['sumblk']=sum(b) if b else -1
    feat[(r,c,t)]=f

