def solve(g):
    H=len(g); W=len(g[0])
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==8]
    cellset=set(cells)
    # pieces: 2x2 square or L tromino (3 of a 2x2)
    pieces=[]
    for r in range(H-1):
        for c in range(W-1):
            blk=[(r+i,c+j) for i in range(2) for j in range(2)]
            if all(p in cellset for p in blk): pieces.append(('S',frozenset(blk),None))
            for m in range(4):
                l=[p for k,p in enumerate(blk) if k!=m]
                if all(p in cellset for p in l): pieces.append(('L',frozenset(l),m))  # m=missing index 0=TL,1=TR,2=BL,3=BR
    tilings=[]
    def bt(rem, used, acc):
        if not rem: tilings.append(list(acc)); return
        first=min(rem)
        for typ,ps,m in pieces:
            if first in ps and ps<=cellset and not (ps&used):
                bt(rem-ps, used|ps, acc+[(typ,ps,m)])
    bt(frozenset(cellset), frozenset(), [])
    return tilings

def render(g, tiling, br_color=1):
    out=[row[:] for row in g]
    for typ,ps,m in tiling:
        if typ=='S': col=1
        else: col={0:2,2:3,1:4,3:br_color}[m]  # missing TL->2, BL->3, TR->4, BR->?
        for r,c in ps: out[r][c]=col
    return out

